def search_contacts(query, **_extra):
    import json, os, datetime, time, re, uuid

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0312000" if __import__("os").path.isdir("./environment_mix/0312000") else "/app/database")

    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []

    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)

    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    def _now_iso():
        return datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"

    def _parse_dt(s):
        if s is None:
            return None
        if not isinstance(s, str):
            return None
        try:
            # accept Z or offset; store comparison in UTC naive
            if s.endswith("Z"):
                s2 = s[:-1] + "+00:00"
            else:
                s2 = s
            dt = datetime.datetime.fromisoformat(s2)
            if dt.tzinfo is not None:
                dt = dt.astimezone(datetime.timezone.utc).replace(tzinfo=None)
            return dt
        except Exception:
            return None

    def _log(endpoint, status, credential_used=None, error_code=None, error_message=None, meta=None, started=None):
        started = started or time.time()
        latency_ms = int((time.time() - started) * 1000)
        ts = _now_iso()
        row = {
            "id": "req_" + uuid.uuid4().hex,
            "endpoint": endpoint,
            "credential_used": credential_used,
            "status": status,
            "error_code": error_code,
            "error_message": error_message,
            "latency_ms": latency_ms,
            "timestamp": ts,
            "meta": meta or {},
        }
        # Prefer request log collection if present.
        log_files = [
            "wa_request_logs.json",
            "wa_usage.json",
            "request_logs.json",
            "usage.json",
            "audit_logs.json",
        ]
        for fn in log_files:
            path = os.path.join(_DB, fn)
            if os.path.exists(path):
                data = _load(fn)
                if not isinstance(data, list):
                    data = []
                data.append(row)
                _save(fn, data)
                return
        # If no log file exists, do not fabricate one; still "observable" via no-op.
        return

    started = time.time()
    endpoint = "search_contacts"

    # Auth: ambient; session must be connected/available.
    # Resolve by checking if any required WA mirror collections exist (minimum proxy for "connected").
    if not (os.path.exists(os.path.join(_DB, "wa_contacts.json")) or os.path.exists(os.path.join(_DB, "wa_chats.json"))):
        _log(endpoint, "error", error_code="UNAUTHORIZED", error_message="WhatsApp session not connected/available.", started=started)
        return _err("UNAUTHORIZED", "WhatsApp session not connected/available.")

    if not isinstance(query, str) or not query.strip():
        _log(endpoint, "error", error_code="VALIDATION_ERROR", error_message="query must be a non-empty string.", started=started)
        return _err("VALIDATION_ERROR", "query must be a non-empty string.", field="query")

    q = query.strip()
    q_lower = q.lower()

    contacts = _load("wa_contacts.json")
    if not isinstance(contacts, list):
        contacts = []

    out = []
    for c in contacts:
        if not isinstance(c, dict):
            continue
        if c.get("status") == "deleted":
            continue

        display_name = c.get("display_name") or ""
        jid = c.get("jid") or ""
        phone = c.get("phone_number_e164") or ""

        match = False
        if isinstance(display_name, str) and q_lower in display_name.lower():
            match = True
        if not match and isinstance(phone, str) and phone:
            # exact or substring match
            if q in phone or q_lower in phone.lower():
                match = True
        if not match and isinstance(jid, str) and jid:
            if q_lower in jid.lower():
                match = True

        if match:
            out.append(c)

    # stable-ish ordering: display_name then jid
    def _k(c):
        dn = c.get("display_name") or ""
        return (dn.lower() if isinstance(dn, str) else "", (c.get("jid") or "").lower() if isinstance(c.get("jid"), str) else "")

    out.sort(key=_k)

    resp = {"contacts": out, "total": len(out)}
    _log(endpoint, "ok", meta={"returned": len(out), "query": q}, started=started)
    return resp

def list_messages(after=None, before=None, sender_phone_number=None, chat_jid=None, query=None, limit=20, page=0, include_context=True, context_before=1, context_after=1, **_extra):
    import json, os, datetime, time, uuid, re

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0312000" if __import__("os").path.isdir("./environment_mix/0312000") else "/app/database")

    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []

    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)

    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    def _now_iso():
        return datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"

    def _parse_dt(s, field_name):
        if s is None:
            return None, None
        if not isinstance(s, str) or not s.strip():
            return None, _err("VALIDATION_ERROR", f"{field_name} must be an ISO-8601 string or null.", field=field_name)
        try:
            ss = s.strip()
            if ss.endswith("Z"):
                ss2 = ss[:-1] + "+00:00"
            else:
                ss2 = ss
            dt = datetime.datetime.fromisoformat(ss2)
            if dt.tzinfo is not None:
                dt = dt.astimezone(datetime.timezone.utc).replace(tzinfo=None)
            return dt, None
        except Exception:
            return None, _err("VALIDATION_ERROR", f"{field_name} must be a valid ISO-8601 timestamp.", field=field_name)

    def _log(endpoint, status, credential_used=None, error_code=None, error_message=None, meta=None, started=None):
        started = started or time.time()
        latency_ms = int((time.time() - started) * 1000)
        ts = _now_iso()
        row = {
            "id": "req_" + uuid.uuid4().hex,
            "endpoint": endpoint,
            "credential_used": credential_used,
            "status": status,
            "error_code": error_code,
            "error_message": error_message,
            "latency_ms": latency_ms,
            "timestamp": ts,
            "meta": meta or {},
        }
        for fn in ["wa_request_logs.json", "wa_usage.json", "request_logs.json", "usage.json", "audit_logs.json"]:
            if os.path.exists(os.path.join(_DB, fn)):
                data = _load(fn)
                if not isinstance(data, list):
                    data = []
                data.append(row)
                _save(fn, data)
                return
        return

    started = time.time()
    endpoint = "list_messages"

    if not (os.path.exists(os.path.join(_DB, "wa_messages.json")) and os.path.exists(os.path.join(_DB, "wa_chats.json"))):
        _log(endpoint, "error", error_code="UNAUTHORIZED", error_message="WhatsApp session not connected/available.", started=started)
        return _err("UNAUTHORIZED", "WhatsApp session not connected/available.")

    if not isinstance(limit, int) or limit < 1 or limit > 100:
        _log(endpoint, "error", error_code="VALIDATION_ERROR", error_message="limit must be an integer between 1 and 100.", started=started)
        return _err("VALIDATION_ERROR", "limit must be an integer between 1 and 100.", field="limit")
    if not isinstance(page, int) or page < 0:
        _log(endpoint, "error", error_code="VALIDATION_ERROR", error_message="page must be an integer >= 0.", started=started)
        return _err("VALIDATION_ERROR", "page must be an integer >= 0.", field="page")
    if not isinstance(include_context, bool):
        _log(endpoint, "error", error_code="VALIDATION_ERROR", error_message="include_context must be a boolean.", started=started)
        return _err("VALIDATION_ERROR", "include_context must be a boolean.", field="include_context")
    if not isinstance(context_before, int) or context_before < 0 or context_before > 50:
        _log(endpoint, "error", error_code="VALIDATION_ERROR", error_message="context_before must be an integer between 0 and 50.", started=started)
        return _err("VALIDATION_ERROR", "context_before must be an integer between 0 and 50.", field="context_before")
    if not isinstance(context_after, int) or context_after < 0 or context_after > 50:
        _log(endpoint, "error", error_code="VALIDATION_ERROR", error_message="context_after must be an integer between 0 and 50.", started=started)
        return _err("VALIDATION_ERROR", "context_after must be an integer between 0 and 50.", field="context_after")

    after_dt, e = _parse_dt(after, "after")
    if e:
        _log(endpoint, "error", error_code=e["error"]["code"], error_message=e["error"]["message"], started=started)
        return e
    before_dt, e = _parse_dt(before, "before")
    if e:
        _log(endpoint, "error", error_code=e["error"]["code"], error_message=e["error"]["message"], started=started)
        return e

    if sender_phone_number is not None and (not isinstance(sender_phone_number, str) or not sender_phone_number.strip()):
        _log(endpoint, "error", error_code="VALIDATION_ERROR", error_message="sender_phone_number must be a non-empty string or null.", started=started)
        return _err("VALIDATION_ERROR", "sender_phone_number must be a non-empty string or null.", field="sender_phone_number")
    if sender_phone_number is not None:
        sp = sender_phone_number.strip()
        if not re.fullmatch(r"^[0-9]{7,15}$", sp):
            _log(endpoint, "error", error_code="VALIDATION_ERROR", error_message="sender_phone_number must be E.164 digits (7-15) with no '+'.", started=started)
            return _err("VALIDATION_ERROR", "sender_phone_number must be E.164 digits (7-15) with no '+'.", field="sender_phone_number")
        sender_phone_number = sp

    if chat_jid is not None and (not isinstance(chat_jid, str) or not chat_jid.strip()):
        _log(endpoint, "error", error_code="VALIDATION_ERROR", error_message="chat_jid must be a non-empty string or null.", started=started)
        return _err("VALIDATION_ERROR", "chat_jid must be a non-empty string or null.", field="chat_jid")
    if chat_jid is not None:
        chat_jid = chat_jid.strip()

    if query is not None and (not isinstance(query, str) or not query.strip()):
        _log(endpoint, "error", error_code="VALIDATION_ERROR", error_message="query must be a non-empty string or null.", started=started)
        return _err("VALIDATION_ERROR", "query must be a non-empty string or null.", field="query")
    q_lower = query.strip().lower() if isinstance(query, str) and query.strip() else None

    messages = _load("wa_messages.json")
    if not isinstance(messages, list):
        messages = []

    # Pre-parse sent_at for comparison/sort; skip invalid rows
    enriched = []
    for m in messages:
        if not isinstance(m, dict):
            continue
        dt = None
        sa = m.get("sent_at")
        if isinstance(sa, str):
            try:
                ssa = sa[:-1] + "+00:00" if sa.endswith("Z") else sa
                dtp = datetime.datetime.fromisoformat(ssa)
                if dtp.tzinfo is not None:
                    dtp = dtp.astimezone(datetime.timezone.utc).replace(tzinfo=None)
                dt = dtp
            except Exception:
                dt = None
        if dt is None:
            continue
        enriched.append((dt, m))

    # Apply filters
    filtered = []
    for dt, m in enriched:
        if after_dt is not None and not (dt > after_dt):
            continue
        if before_dt is not None and not (dt < before_dt):
            continue
        if sender_phone_number is not None:
            if (m.get("sender_phone_number_e164") or None) != sender_phone_number:
                continue
        if chat_jid is not None:
            if (m.get("chat_jid") or None) != chat_jid:
                continue
        if q_lower is not None:
            txt = m.get("text")
            if not (isinstance(txt, str) and q_lower in txt.lower()):
                continue
        filtered.append((dt, m))

    # Order by sent_at desc (newest first)
    filtered.sort(key=lambda x: x[0], reverse=True)

    total = len(filtered)
    start = page * limit
    end = start + limit
    page_items = filtered[start:end]
    has_more = end < total

    # Build chat->sorted messages for context lookup if needed
    if include_context:
        by_chat = {}
        for dt, m in enriched:
            cid = m.get("chat_id")
            if not isinstance(cid, str) or not cid:
                continue
            by_chat.setdefault(cid, []).append((dt, m))
        for cid in by_chat:
            by_chat[cid].sort(key=lambda x: x[0])  # ascending for neighbor lookup

        def _context_for_message(msg):
            cid = msg.get("chat_id")
            if cid not in by_chat:
                return {"before": [], "after": []}
            arr = by_chat[cid]
            # find index by external_message_id match (preferred), fallback to id match
            target_ext = msg.get("external_message_id")
            target_id = msg.get("id")
            idx = None
            for i, (_, mm) in enumerate(arr):
                if target_ext is not None and mm.get("external_message_id") == target_ext and mm.get("chat_jid") == msg.get("chat_jid"):
                    idx = i
                    break
            if idx is None and target_id is not None:
                for i, (_, mm) in enumerate(arr):
                    if mm.get("id") == target_id:
                        idx = i
                        break
            if idx is None:
                return {"before": [], "after": []}
            b0 = max(0, idx - context_before)
            a1 = min(len(arr), idx + 1 + context_after)
            before_msgs = [mm for _, mm in arr[b0:idx]]
            after_msgs = [mm for _, mm in arr[idx + 1:a1]]
            return {"before": before_msgs, "after": after_msgs}

        results = []
        for _, m in page_items:
            item = dict(m)
            item["context"] = _context_for_message(m)
            results.append(item)
    else:
        results = [m for _, m in page_items]

    resp = {
        "messages": results,
        "total": total,
        "page": page,
        "limit": limit,
        "has_more": has_more,
        "next_cursor": (page + 1) if has_more else None,
    }
    _log(
        endpoint,
        "ok",
        meta={
            "filters": {
                "after": after,
                "before": before,
                "sender_phone_number": sender_phone_number,
                "chat_jid": chat_jid,
                "query": query,
                "include_context": include_context,
                "context_before": context_before,
                "context_after": context_after,
            },
            "returned": len(results),
            "total": total,
            "page": page,
            "limit": limit,
        },
        started=started,
    )
    return resp

def list_chats(query=None, limit=20, page=0, include_last_message=True, sort_by="last_active", **_extra):
    import json, os, datetime, time, uuid

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0312000" if __import__("os").path.isdir("./environment_mix/0312000") else "/app/database")

    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []

    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)

    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    def _now_iso():
        return datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"

    def _log(endpoint, status, credential_used=None, error_code=None, error_message=None, meta=None, started=None):
        started = started or time.time()
        latency_ms = int((time.time() - started) * 1000)
        ts = _now_iso()
        row = {
            "id": "req_" + uuid.uuid4().hex,
            "endpoint": endpoint,
            "credential_used": credential_used,
            "status": status,
            "error_code": error_code,
            "error_message": error_message,
            "latency_ms": latency_ms,
            "timestamp": ts,
            "meta": meta or {},
        }
        for fn in ["wa_request_logs.json", "wa_usage.json", "request_logs.json", "usage.json", "audit_logs.json"]:
            if os.path.exists(os.path.join(_DB, fn)):
                data = _load(fn)
                if not isinstance(data, list):
                    data = []
                data.append(row)
                _save(fn, data)
                return
        return

    started = time.time()
    endpoint = "list_chats"

    if not os.path.exists(os.path.join(_DB, "wa_chats.json")):
        _log(endpoint, "error", error_code="UNAUTHORIZED", error_message="WhatsApp session not connected/available.", started=started)
        return _err("UNAUTHORIZED", "WhatsApp session not connected/available.")

    if query is not None and (not isinstance(query, str) or not query.strip()):
        _log(endpoint, "error", error_code="VALIDATION_ERROR", error_message="query must be a non-empty string or null.", started=started)
        return _err("VALIDATION_ERROR", "query must be a non-empty string or null.", field="query")
    if not isinstance(limit, int) or limit < 1 or limit > 100:
        _log(endpoint, "error", error_code="VALIDATION_ERROR", error_message="limit must be an integer between 1 and 100.", started=started)
        return _err("VALIDATION_ERROR", "limit must be an integer between 1 and 100.", field="limit")
    if not isinstance(page, int) or page < 0:
        _log(endpoint, "error", error_code="VALIDATION_ERROR", error_message="page must be an integer >= 0.", started=started)
        return _err("VALIDATION_ERROR", "page must be an integer >= 0.", field="page")
    if not isinstance(include_last_message, bool):
        _log(endpoint, "error", error_code="VALIDATION_ERROR", error_message="include_last_message must be a boolean.", started=started)
        return _err("VALIDATION_ERROR", "include_last_message must be a boolean.", field="include_last_message")
    if not isinstance(sort_by, str) or sort_by not in ["last_active", "title"]:
        _log(endpoint, "error", error_code="VALIDATION_ERROR", error_message="sort_by must be one of ['last_active','title'].", started=started)
        return _err("VALIDATION_ERROR", "sort_by must be one of ['last_active','title'].", field="sort_by")

    q_lower = query.strip().lower() if isinstance(query, str) and query.strip() else None

    chats = _load("wa_chats.json")
    if not isinstance(chats, list):
        chats = []

    # Optional last message join
    msg_by_id = {}
    if include_last_message and os.path.exists(os.path.join(_DB, "wa_messages.json")):
        msgs = _load("wa_messages.json")
        if isinstance(msgs, list):
            for m in msgs:
                if isinstance(m, dict) and isinstance(m.get("id"), str):
                    msg_by_id[m["id"]] = m

    filtered = []
    for c in chats:
        if not isinstance(c, dict):
            continue
        if q_lower is not None:
            title = c.get("title") or ""
            jid = c.get("chat_jid") or ""
            ok = False
            if isinstance(title, str) and q_lower in title.lower():
                ok = True
            if not ok and isinstance(jid, str) and q_lower in jid.lower():
                ok = True
            if not ok:
                continue
        filtered.append(c)

    def _parse_dt(s):
        if not isinstance(s, str):
            return None
        try:
            ss = s[:-1] + "+00:00" if s.endswith("Z") else s
            dt = datetime.datetime.fromisoformat(ss)
            if dt.tzinfo is not None:
                dt = dt.astimezone(datetime.timezone.utc).replace(tzinfo=None)
            return dt
        except Exception:
            return None

    if sort_by == "title":
        filtered.sort(key=lambda c: ((c.get("title") or "").lower() if isinstance(c.get("title"), str) else "", (c.get("chat_jid") or "").lower()))
    else:
        # last_active desc; nulls last; tie-breaker updated_at desc
        def _k(c):
            la = _parse_dt(c.get("last_active_at"))
            ua = _parse_dt(c.get("updated_at"))
            la_key = la if la is not None else datetime.datetime.min
            ua_key = ua if ua is not None else datetime.datetime.min
            return (la_key, ua_key)

        filtered.sort(key=_k, reverse=True)

    total = len(filtered)
    start = page * limit
    end = start + limit
    page_chats = filtered[start:end]
    has_more = end < total

    results = []
    for c in page_chats:
        row = dict(c)
        if include_last_message:
            lm_id = c.get("last_message_id")
            row["last_message"] = msg_by_id.get(lm_id) if isinstance(lm_id, str) else None
        results.append(row)

    resp = {
        "chats": results,
        "total": total,
        "page": page,
        "limit": limit,
        "has_more": has_more,
        "next_cursor": (page + 1) if has_more else None,
    }
    _log(
        endpoint,
        "ok",
        meta={"query": query, "returned": len(results), "total": total, "page": page, "limit": limit, "include_last_message": include_last_message, "sort_by": sort_by},
        started=started,
    )
    return resp

def get_chat(chat_jid, include_last_message=True, **_extra):
    import json, os, datetime, time, uuid

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0312000" if __import__("os").path.isdir("./environment_mix/0312000") else "/app/database")

    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []

    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)

    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    def _now_iso():
        return datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"

    def _log(endpoint, status, credential_used=None, error_code=None, error_message=None, meta=None, started=None):
        started = started or time.time()
        latency_ms = int((time.time() - started) * 1000)
        ts = _now_iso()
        row = {
            "id": "req_" + uuid.uuid4().hex,
            "endpoint": endpoint,
            "credential_used": credential_used,
            "status": status,
            "error_code": error_code,
            "error_message": error_message,
            "latency_ms": latency_ms,
            "timestamp": ts,
            "meta": meta or {},
        }
        for fn in ["wa_request_logs.json", "wa_usage.json", "request_logs.json", "usage.json", "audit_logs.json"]:
            if os.path.exists(os.path.join(_DB, fn)):
                data = _load(fn)
                if not isinstance(data, list):
                    data = []
                data.append(row)
                _save(fn, data)
                return
        return

    started = time.time()
    endpoint = "get_chat"

    if not os.path.exists(os.path.join(_DB, "wa_chats.json")):
        _log(endpoint, "error", error_code="UNAUTHORIZED", error_message="WhatsApp session not connected/available.", started=started)
        return _err("UNAUTHORIZED", "WhatsApp session not connected/available.")

    if not isinstance(chat_jid, str) or not chat_jid.strip():
        _log(endpoint, "error", error_code="VALIDATION_ERROR", error_message="chat_jid must be a non-empty string.", started=started)
        return _err("VALIDATION_ERROR", "chat_jid must be a non-empty string.", field="chat_jid")
    if not isinstance(include_last_message, bool):
        _log(endpoint, "error", error_code="VALIDATION_ERROR", error_message="include_last_message must be a boolean.", started=started)
        return _err("VALIDATION_ERROR", "include_last_message must be a boolean.", field="include_last_message")

    cj = chat_jid.strip()
    chats = _load("wa_chats.json")
    if not isinstance(chats, list):
        chats = []

    chat = None
    for c in chats:
        if isinstance(c, dict) and c.get("chat_jid") == cj:
            chat = c
            break

    if chat is None:
        _log(endpoint, "error", error_code="NOT_FOUND", error_message="Chat not found.", meta={"chat_jid": cj}, started=started)
        return _err("NOT_FOUND", "Chat not found.", chat_jid=cj)

    result = dict(chat)

    if include_last_message:
        lm = None
        lm_id = chat.get("last_message_id")
        if isinstance(lm_id, str) and os.path.exists(os.path.join(_DB, "wa_messages.json")):
            msgs = _load("wa_messages.json")
            if isinstance(msgs, list):
                for m in msgs:
                    if isinstance(m, dict) and m.get("id") == lm_id:
                        lm = m
                        break
        result["last_message"] = lm

    resp = {"chat": result}
    _log(endpoint, "ok", meta={"chat_jid": cj, "include_last_message": include_last_message}, started=started)
