def get_direct_chat_by_contact(sender_phone_number, **_extra):
    import json, os, datetime, time, re

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0312000" if __import__("os").path.isdir("./environment_mix/0312000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    def _iso_now():
        return datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"
    def _parse_dt(v):
        if not v or not isinstance(v, str):
            return None
        try:
            if v.endswith("Z"):
                return datetime.datetime.fromisoformat(v[:-1] + "+00:00")
            return datetime.datetime.fromisoformat(v)
        except Exception:
            return None

    def _log(status, error_code=None):
        fname = "wa_request_logs.json"
        path = os.path.join(_DB, fname)
        if not os.path.exists(path):
            return
        logs = _load(fname)
        if not isinstance(logs, list):
            logs = []
        logs.append({
            "id": "walog_" + datetime.datetime.utcnow().strftime("%Y%m%d%H%M%S%f"),
            "endpoint": "get_direct_chat_by_contact",
            "status": status,
            "error_code": error_code,
            "latency_ms": int((time.time() - t0) * 1000),
            "created_at": _iso_now(),
        })
        _save(fname, logs)

    if not isinstance(sender_phone_number, str) or not sender_phone_number.strip():
        _log("error", "VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "sender_phone_number must be a non-empty string.", field="sender_phone_number")
    sender_phone_number = sender_phone_number.strip()
    if not re.fullmatch(r"^[0-9]{7,15}$", sender_phone_number):
        _log("error", "VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "sender_phone_number must be 7-15 digits (E.164 digits only, no '+').", field="sender_phone_number")

    contacts = _load("wa_contacts.json")
    chats = _load("wa_chats.json")
    if not isinstance(contacts, list):
        contacts = []
    if not isinstance(chats, list):
        chats = []

    # Resolve contact by phone_number_e164 primarily; fall back to matching jid localpart.
    contact = None
    for c in contacts:
        if isinstance(c, dict) and c.get("status") != "deleted" and c.get("phone_number_e164") == sender_phone_number:
            contact = c
            break
    if contact is None:
        # fallback: jid like "<digits>@s.whatsapp.net"
        for c in contacts:
            if not isinstance(c, dict) or c.get("status") == "deleted":
                continue
            jid = c.get("jid")
            if isinstance(jid, str) and jid.startswith(sender_phone_number) and "@s.whatsapp.net" in jid:
                contact = c
                break

    if contact is None:
        _log("error", "NOT_FOUND")
        return _err("NOT_FOUND", "No contact found for that phone number.", sender_phone_number=sender_phone_number)

    # Find direct chats tied to this contact; choose most recently active.
    candidates = []
    for ch in chats:
        if not isinstance(ch, dict):
            continue
        if ch.get("status") == "deleted":
            continue
        if ch.get("chat_type") != "direct":
            continue
        if ch.get("direct_contact_id") != contact.get("id"):
            continue
        candidates.append(ch)

    if not candidates:
        _log("error", "NOT_FOUND")
        return _err("NOT_FOUND", "No direct chat found for that phone number.", sender_phone_number=sender_phone_number, contact_id=contact.get("id"))

    def _sort_key(ch):
        dt = _parse_dt(ch.get("last_active_at")) or _parse_dt(ch.get("updated_at")) or _parse_dt(ch.get("created_at"))
        if dt is None:
            dt = datetime.datetime(1970, 1, 1, tzinfo=datetime.timezone.utc)
        return dt

    candidates.sort(key=_sort_key, reverse=True)
    chat = candidates[0]

    _log("ok", None)
    return {"chat": chat, "contact": {"id": contact.get("id"), "jid": contact.get("jid"), "phone_number_e164": contact.get("phone_number_e164"), "display_name": contact.get("display_name")}}

def get_contact_chats(jid, limit=None, page=None, **_extra):
    import json, os, datetime, time
    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0312000" if __import__("os").path.isdir("./environment_mix/0312000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f: return json.load(f)
        except Exception: return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f: json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x): return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    logs = _load("wa_request_logs.json")
    def _log(status, error_code=None):
        try:
            row = {
                "id": f"walog_{datetime.datetime.utcnow().strftime('%Y%m%d%H%M%S%f')}",
                "endpoint": "get_contact_chats",
                "status": status,
                "error_code": error_code,
                "latency_ms": int((time.time() - t0) * 1000),
                "created_at": datetime.datetime.utcnow().isoformat() + "Z",
            }
            if isinstance(logs, list):
                logs.append(row)
                _save("wa_request_logs.json", logs)
        except Exception:
            pass

    sessions = _load("wa_sessions.json")
    if isinstance(sessions, list) and len(sessions) > 0:
        if not any((s.get("status") in ("connected", "active", "ready")) for s in sessions if isinstance(s, dict)):
            _log("error", "UNAUTHORIZED")
            return _err("UNAUTHORIZED", "WhatsApp session is not connected/available.")

    if not isinstance(jid, str) or not jid.strip():
        _log("error", "VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "jid must be a non-empty string.")
    jid = jid.strip()

    if limit is None:
        limit = 20
    if page is None:
        page = 0
    if not isinstance(limit, int) or not (1 <= limit <= 100):
        _log("error", "VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "limit must be an integer between 1 and 100.")
    if not isinstance(page, int) or page < 0:
        _log("error", "VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "page must be an integer >= 0.")

    contacts = _load("wa_contacts.json")
    if not isinstance(contacts, list):
        contacts = []
    contact = None
    for c in contacts:
        if isinstance(c, dict) and c.get("jid") == jid:
            contact = c
            break
    if not contact or contact.get("status") == "deleted":
        _log("error", "NOT_FOUND")
        return _err("NOT_FOUND", "Contact not found in local mirror.")

    chats = _load("wa_chats.json")
    if not isinstance(chats, list):
        chats = []
    parts = _load("wa_chat_participants.json")
    if not isinstance(parts, list):
        parts = []

    contact_id = contact.get("id")
    active_participations = set()
    for p in parts:
        if not isinstance(p, dict):
            continue
        if p.get("contact_id") == contact_id and p.get("status") == "active":
            cid = p.get("chat_id")
            if isinstance(cid, str) and cid:
                active_participations.add(cid)

    involved = []
    for ch in chats:
        if not isinstance(ch, dict):
            continue
        if ch.get("status") == "deleted":
            continue
        if ch.get("direct_contact_id") == contact_id or ch.get("id") in active_participations:
            involved.append(ch)

    def _parse_dt(x):
        if not x or not isinstance(x, str):
            return None
        s = x.strip()
        try:
            if s.endswith("Z"):
                s = s[:-1] + "+00:00"
            return datetime.datetime.fromisoformat(s)
        except Exception:
            return None

    involved.sort(key=lambda ch: (_parse_dt(ch.get("last_active_at")) or _parse_dt(ch.get("updated_at")) or _parse_dt(ch.get("created_at")) or datetime.datetime.min.replace(tzinfo=datetime.timezone.utc)), reverse=True)

    total = len(involved)
    start = page * limit
    end = start + limit
    page_rows = involved[start:end] if start < total else []

    _log("ok")
    return {
        "chats": page_rows,
        "pagination": {
            "limit": limit,
            "page": page,
            "total": total,
            "has_more": end < total
        },
        "contact": contact
    }

