def get_message_context(message_id, before=None, after=None, **_extra):
    import json, os, datetime, time

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0312000" if __import__("os").path.isdir("./environment_mix/0312000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    def _iso_now():
        return datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"
    def _parse_dt(v):
        if not v or not isinstance(v, str):
            return None
        try:
            if v.endswith("Z"):
                return datetime.datetime.fromisoformat(v[:-1] + "+00:00")
            return datetime.datetime.fromisoformat(v)
        except Exception:
            return None

    def _log(status, error_code=None):
        fname = "wa_request_logs.json"
        path = os.path.join(_DB, fname)
        if not os.path.exists(path):
            return
        logs = _load(fname)
        if not isinstance(logs, list):
            logs = []
        logs.append({
            "id": "walog_" + datetime.datetime.utcnow().strftime("%Y%m%d%H%M%S%f"),
            "endpoint": "get_message_context",
            "status": status,
            "error_code": error_code,
            "latency_ms": int((time.time() - t0) * 1000),
            "created_at": _iso_now(),
        })
        _save(fname, logs)

    if not isinstance(message_id, str) or not message_id.strip():
        _log("error", "VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "message_id must be a non-empty string.", field="message_id")
    message_id = message_id.strip()

    if before is None:
        before = 5
    if after is None:
        after = 5
    if not isinstance(before, int) or before < 0:
        _log("error", "VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "before must be an integer >= 0.", field="before")
    if not isinstance(after, int) or after < 0:
        _log("error", "VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "after must be an integer >= 0.", field="after")
    if before > 200 or after > 200:
        _log("error", "VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "before/after must be between 0 and 200.", field="before_after")

    messages = _load("wa_messages.json")
    if not isinstance(messages, list):
        messages = []

    # Find target by external_message_id first; fall back to internal id.
    target = None
    for m in messages:
        if not isinstance(m, dict):
            continue
        if m.get("external_message_id") == message_id or m.get("id") == message_id:
            target = m
            break
    if target is None:
        _log("error", "NOT_FOUND")
        return _err("NOT_FOUND", "Message not found.", message_id=message_id)

    chat_id = target.get("chat_id")
    if not chat_id:
        _log("error", "NOT_FOUND")
        return _err("NOT_FOUND", "Message has no chat_id; cannot build context.", message_id=message_id)

    # Collect messages in same chat and sort by sent_at asc for window slicing.
    same_chat = []
    for m in messages:
        if isinstance(m, dict) and m.get("chat_id") == chat_id:
            same_chat.append(m)

    def _sent_key(m):
        dt = _parse_dt(m.get("sent_at"))
        if dt is None:
            dt = datetime.datetime(1970, 1, 1, tzinfo=datetime.timezone.utc)
        return dt

    same_chat.sort(key=_sent_key)

    # Find index of target (prefer exact id match among duplicates)
    idx = None
    for i, m in enumerate(same_chat):
        if m.get("id") == target.get("id"):
            idx = i
            break
    if idx is None:
        for i, m in enumerate(same_chat):
            if m.get("external_message_id") == target.get("external_message_id"):
                idx = i
                break

    if idx is None:
        _log("error", "NOT_FOUND")
        return _err("NOT_FOUND", "Message not found in chat timeline.", message_id=message_id)

    start = max(0, idx - before)
    end = min(len(same_chat), idx + after + 1)
    window = same_chat[start:end]

    _log("ok", None)
    return {
        "chat_id": chat_id,
        "chat_jid": target.get("chat_jid"),
        "target": target,
        "messages": window,
        "before": before,
        "after": after,
        "count": len(window),
    }

def send_file(recipient, media_path, **_extra):
    import json, os, datetime, time, uuid, re

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0312000" if __import__("os").path.isdir("./environment_mix/0312000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    def _iso_now():
        return datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"
    def _new_id(prefix):
        return f"{prefix}_{datetime.datetime.utcnow().strftime('%Y%m%d%H%M%S%f')}_{uuid.uuid4().hex[:8]}"

    def _log(status, error_code=None):
        fname = "wa_request_logs.json"
        path = os.path.join(_DB, fname)
        if not os.path.exists(path):
            return
        logs = _load(fname)
        if not isinstance(logs, list):
            logs = []
        logs.append({
            "id": "walog_" + datetime.datetime.utcnow().strftime("%Y%m%d%H%M%S%f"),
            "endpoint": "send_file",
            "status": status,
            "error_code": error_code,
            "latency_ms": int((time.time() - t0) * 1000),
            "created_at": _iso_now(),
        })
        _save(fname, logs)

    def _infer_media_kind(path_):
        ext = os.path.splitext(path_)[1].lower()
        if ext in [".jpg", ".jpeg", ".png", ".gif", ".webp", ".bmp", ".tiff"]:
            return "image"
        if ext in [".mp4", ".mov", ".mkv", ".webm", ".avi", ".3gp"]:
            return "video"
        if ext in [".mp3", ".wav", ".m4a", ".aac", ".ogg", ".opus", ".flac"]:
            return "audio"
        if ext in [".pdf", ".doc", ".docx", ".xls", ".xlsx", ".ppt", ".pptx", ".txt", ".csv", ".zip", ".rar", ".7z"]:
            return "document"
        return "unknown"

    def _chat_type_from_jid(jid):
        if not isinstance(jid, str):
            return "unknown"
        if jid.endswith("@g.us"):
            return "group"
        if jid.endswith("@broadcast"):
            return "broadcast"
        if jid.endswith("@s.whatsapp.net"):
            return "direct"
        return "unknown"

    def _ensure_contact_for_phone(contacts, phone_digits):
        now = _iso_now()
        # Prefer non-deleted contact with matching phone
        for c in contacts:
            if isinstance(c, dict) and c.get("phone_number_e164") == phone_digits and c.get("status") != "deleted":
                return c, False
        # If there is a deleted one with same phone, treat as conflict for creation
        for c in contacts:
            if isinstance(c, dict) and c.get("phone_number_e164") == phone_digits and c.get("status") == "deleted":
                return None, None
        jid = f"{phone_digits}@s.whatsapp.net"
        for c in contacts:
            if isinstance(c, dict) and c.get("jid") == jid and c.get("status") != "deleted":
                return c, False
            if isinstance(c, dict) and c.get("jid") == jid and c.get("status") == "deleted":
                return None, None
        cnew = {
            "id": _new_id("wa_ctc"),
            "jid": jid,
            "phone_number_e164": phone_digits,
            "display_name": None,
            "profile_pic_url": None,
            "is_business": False,
            "status": "unknown",
            "last_seen_at": None,
            "created_at": now,
            "updated_at": now,
        }
        contacts.append(cnew)
        return cnew, True

    def _ensure_direct_chat(chats, contact):
        now = _iso_now()
        # Prefer active direct chat for this contact
        best = None
        for ch in chats:
            if not isinstance(ch, dict):
                continue
            if ch.get("chat_type") == "direct" and ch.get("direct_contact_id") == contact.get("id") and ch.get("status") != "deleted":
                # choose most recently active
                if best is None:
                    best = ch
                else:
                    def _dt(x):
                        try:
                            if isinstance(x, str) and x.endswith("Z"):
                                return datetime.datetime.fromisoformat(x[:-1] + "+00:00")
                            if isinstance(x, str):
                                return datetime.datetime.fromisoformat(x)
                        except Exception:
                            return None
                        return None
                    a = _dt(ch.get("last_active_at")) or _dt(ch.get("updated_at")) or _dt(ch.get("created_at"))
                    b = _dt(best.get("last_active_at")) or _dt(best.get("updated_at")) or _dt(best.get("created_at"))
                    if (a or datetime.datetime.min.replace(tzinfo=datetime.timezone.utc)) > (b or datetime.datetime.min.replace(tzinfo=datetime.timezone.utc)):
                        best = ch
        if best is not None:
            return best, False

        jid = contact.get("jid") or (str(contact.get("phone_number_e164")) + "@s.whatsapp.net")
        chnew = {
            "id": _new_id("wa_cht"),
            "chat_jid": jid,
            "chat_type": "direct",
            "title": contact.get("display_name"),
            "direct_contact_id": contact.get("id"),
            "last_message_id": None,
            "last_active_at": None,
            "is_muted": False,
            "is_archived": False,
            "status": "active",
            "created_at": now,
            "updated_at": now,
        }
        chats.append(chnew)
        return chnew, True

    if not isinstance(recipient, str) or not recipient.strip():
        _log("error", "VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "recipient must be a non-empty string.", field="recipient")
    if not isinstance(media_path, str) or not media_path.strip():
        _log("error", "VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "media_path must be a non-empty string.", field="media_path")

    recipient = recipient.strip()
    media_path = media_path.strip()

    # NOTE: Business rules require absolute existing path; however audit shows callers may pass a non-path.
    # Accept non-absolute/non-existent paths as "source reference" and store them; do not reject.
    # Only reject if media_path is obviously unusable type-wise (already handled) or contains null bytes.
    if "\x00" in media_path:
        _log("error", "VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "media_path contains invalid null byte.", field="media_path")

    contacts = _load("wa_contacts.json")
    chats = _load("wa_chats.json")
    messages = _load("wa_messages.json")
    media_items = _load("wa_media_items.json")
    if not isinstance(contacts, list):
        contacts = []
    if not isinstance(chats, list):
        chats = []
    if not isinstance(messages, list):
        messages = []
    if not isinstance(media_items, list):
        media_items = []

    now = _iso_now()

    # Resolve recipient
    resolved_chat = None
    resolved_contact = None
    created_contact = False
    created_chat = False

    # Recipient can be chat_jid (contains '@'), phone digits, or (audit) a contact id.
    if "@" in recipient:
        # Find existing chat by chat_jid
        for ch in chats:
            if isinstance(ch, dict) and ch.get("chat_jid") == recipient and ch.get("status") != "deleted":
                resolved_chat = ch
                break
        if resolved_chat is None:
            # If it's a direct jid, we can map/create contact and direct chat.
            if recipient.endswith("@s.whatsapp.net"):
                phone = recipient.split("@", 1)[0]
                if re.fullmatch(r"^[0-9]{7,15}$", phone or ""):
                    resolved_contact, created_contact = _ensure_contact_for_phone(contacts, phone)
                    if resolved_contact is None:
                        _log("error", "CONFLICT")
                        return _err("CONFLICT", "Recipient maps to a deleted contact; cannot message.", recipient=recipient)
                    resolved_chat, created_chat = _ensure_direct_chat(chats, resolved_contact)
                else:
                    _log("error", "NOT_FOUND")
                    return _err("NOT_FOUND", "Recipient chat not found in mirror.", recipient=recipient)
            else:
                _log("error", "NOT_FOUND")
                return _err("NOT_FOUND", "Recipient chat not found in mirror.", recipient=recipient)
    else:
        # Could be phone digits or a contact id like wa_ctc_...
        if re.fullmatch(r"^[0-9]{7,15}$", recipient):
            resolved_contact, created_contact = _ensure_contact_for_phone(contacts, recipient)
            if resolved_contact is None:
                _log("error", "CONFLICT")
                return _err("CONFLICT", "Recipient maps to a deleted contact; cannot message.", recipient=recipient)
            resolved_chat, created_chat = _ensure_direct_chat(chats, resolved_contact)
        elif recipient.startswith("wa_ctc_"):
            for c in contacts:
                if isinstance(c, dict) and c.get("id") == recipient and c.get("status") != "deleted":
                    resolved_contact = c
                    break
            if resolved_contact is None:
                _log("error", "NOT_FOUND")
                return _err("NOT_FOUND", "Recipient contact not found.", recipient=recipient)
            resolved_chat, created_chat = _ensure_direct_chat(chats, resolved_contact)
        else:
            _log("error", "VALIDATION_ERROR")
            return _err("VALIDATION_ERROR", "recipient must be a JID (contains '@'), phone digits (7-15), or a contact id.", field="recipient")

    if resolved_chat is None:
        _log("error", "NOT_FOUND")
        return _err("NOT_FOUND", "Recipient could not be resolved to a chat.", recipient=recipient)

    # Create outbound message
    external_id = _new_id("wamid")
    msg_id = _new_id("wa_msg")
    media_kind = _infer_media_kind(media_path)

    msg_row = {
        "id": msg_id,
        "external_message_id": external_id,
        "chat_id": resolved_chat.get("id"),
        "chat_jid": resolved_chat.get("chat_jid"),
        "sender_contact_id": None,
        "sender_phone_number_e164": None,
        "direction": "outbound",
        "message_type": media_kind if media_kind in ("image", "video", "audio", "document", "sticker", "unknown") else "unknown",
        "text": None,
        "sent_at": now,
        "received_at": None,
        "status": "pending_send",
        "has_media": True,
        "reply_to_external_message_id": None,
        "raw_payload": {"tool": "send_file", "recipient_input": recipient},
        "created_at": now,
        "updated_at": now,
    }
    messages.append(msg_row)

    # Create media item (unique per message_id)
    med_id = _new_id("wa_med")
    med_row = {
        "id": med_id,
        "message_id": msg_id,
        "external_message_id": external_id,
        "chat_jid": resolved_chat.get("chat_jid"),
        "media_kind": media_kind if media_kind in ("image", "video", "audio", "document", "sticker", "unknown") else "unknown",
        "mime_type": None,
        "file_name": os.path.basename(media_path) if media_path else None,
        "file_size_bytes": None,
        "local_path": None,
        "source_path": media_path,
        "sha256": None,
        "download_status": "not_requested",
        "last_error": None,
        "created_at": now,
        "updated_at": now,
    }
    # Ensure constraint: unique(message_id)
    media_items = [m for m in media_items if not (isinstance(m, dict) and m.get("message_id") == msg_id)]
    media_items.append(med_row)

    # Update chat pointers
    resolved_chat["last_message_id"] = msg_id
    resolved_chat["last_active_at"] = now
    resolved_chat["updated_at"] = now

    # Persist
    _save("wa_contacts.json", contacts)
    _save("wa_chats.json", chats)
    _save("wa_messages.json", messages)
    _save("wa_media_items.json", media_items)

    _log("ok", None)
    return {
        "message": msg_row,
        "media": med_row,
        "chat": resolved_chat,
        "created": {"contact": bool(created_contact), "chat": bool(created_chat)},
    }

