def download_media(message_id, chat_jid, **_extra):
    import json, os, datetime, time, uuid, re

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0312000" if __import__("os").path.isdir("./environment_mix/0312000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    def _iso_now():
        return datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"
    def _new_id(prefix):
        return f"{prefix}_{datetime.datetime.utcnow().strftime('%Y%m%d%H%M%S%f')}_{uuid.uuid4().hex[:8]}"

    def _log(status, error_code=None):
        fname = "wa_request_logs.json"
        path = os.path.join(_DB, fname)
        if not os.path.exists(path):
            return
        logs = _load(fname)
        if not isinstance(logs, list):
            logs = []
        logs.append({
            "id": "walog_" + datetime.datetime.utcnow().strftime("%Y%m%d%H%M%S%f"),
            "endpoint": "download_media",
            "status": status,
            "error_code": error_code,
            "latency_ms": int((time.time() - t0) * 1000),
            "created_at": _iso_now(),
        })
        _save(fname, logs)

    if not isinstance(message_id, str) or not message_id.strip():
        _log("error", "VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "message_id is required and must be a non-empty string.", field="message_id")
    if not isinstance(chat_jid, str) or not chat_jid.strip():
        _log("error", "VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "chat_jid is required and must be a non-empty string.", field="chat_jid")

    message_id = message_id.strip()
    chat_jid = chat_jid.strip()

    if not re.fullmatch(r"^[^@\s]+@[^@\s]+$", chat_jid):
        _log("error", "VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "chat_jid is invalid.", field="chat_jid")

    msgs = _load("wa_messages.json")
    media = _load("wa_media_items.json")
    if not isinstance(msgs, list):
        msgs = []
    if not isinstance(media, list):
        media = []

    # Locate message by external_message_id AND chat_jid; if none, fall back to internal id match.
    msg = None
    for m in msgs:
        if not isinstance(m, dict):
            continue
        if m.get("chat_jid") != chat_jid:
            continue
        if m.get("external_message_id") == message_id:
            msg = m
            break
    if msg is None:
        for m in msgs:
            if not isinstance(m, dict):
                continue
            if m.get("chat_jid") != chat_jid:
                continue
            if m.get("id") == message_id:
                msg = m
                break

    if msg is None:
        _log("error", "NOT_FOUND")
        return _err("NOT_FOUND", "Message not found.", message_id=message_id, chat_jid=chat_jid)

    if not msg.get("has_media"):
        _log("error", "CONFLICT")
        return _err("CONFLICT", "Message has no media to download.", message_id=message_id, chat_jid=chat_jid)

    now = _iso_now()
    # Find or create media item for this message
    item = None
    for it in media:
        if not isinstance(it, dict):
            continue
        if it.get("message_id") == msg.get("id"):
            item = it
            break

    if item is None:
        item = {
            "id": _new_id("wa_med"),
            "message_id": msg.get("id"),
            "external_message_id": msg.get("external_message_id"),
            "chat_jid": chat_jid,
            "media_kind": msg.get("message_type") if msg.get("message_type") in ("image", "video", "audio", "document", "sticker", "unknown") else "unknown",
            "mime_type": None,
            "file_name": None,
            "file_size_bytes": None,
            "local_path": None,
            "source_path": None,
            "sha256": None,
            "download_status": "not_requested",
            "last_error": None,
            "created_at": now,
            "updated_at": now,
        }
        media.append(item)

    # Enforce lifecycle transitions for download_status
    cur = item.get("download_status") or "not_requested"
    allowed = {
        "not_requested": ["queued"],
        "queued": ["downloading", "failed"],
        "downloading": ["available", "failed"],
        "available": [],
        "failed": ["queued"],
    }
    if cur == "available" and item.get("local_path"):
        # Idempotent: already available
        _log("ok", None)
        return {"media": item, "status": "available", "local_path": item.get("local_path"), "message": msg}

    if cur not in allowed:
        _log("error", "INVALID_TRANSITION")
        return _err("INVALID_TRANSITION", "Invalid download_status state on media item.", download_status=cur, media_id=item.get("id"))

    if cur == "failed":
        if "queued" not in allowed[cur]:
            _log("error", "INVALID_TRANSITION")
            return _err("INVALID_TRANSITION", "Cannot re-queue from failed.", media_id=item.get("id"))
        item["download_status"] = "queued"
        item["last_error"] = None
        item["updated_at"] = now
    elif cur == "not_requested":
        item["download_status"] = "queued"
        item["updated_at"] = now
    elif cur in ("queued", "downloading"):
        # already in progress; leave as-is (idempotent request)
        item["updated_at"] = now

    # Simulate completion immediately by making it "available" with a deterministic local_path.
    # This keeps observable state changes and matches the rule "upon completion set local_path and available".
    if item.get("download_status") == "queued":
        item["download_status"] = "downloading"
        item["updated_at"] = now

    # Completion
    safe_ext = None
    mk = item.get("media_kind") or "unknown"
    if mk == "image":
        safe_ext = ".jpg"
    elif mk == "video":
        safe_ext = ".mp4"
    elif mk == "audio":
        safe_ext = ".m4a"
    elif mk == "document":
        safe_ext = ".bin"
    elif mk == "sticker":
        safe_ext = ".webp"
    else:
        safe_ext = ".bin"

    local_dir = os.path.join(_DB, "wa_media_downloads")
    try:
        os.makedirs(local_dir, exist_ok=True)
    except Exception:
        # If directory can't be created, mark failed (expected operational failure)
        item["download_status"] = "failed"
        item["last_error"] = "Unable to create local media directory."
        item["updated_at"] = now
        _save("wa_media_items.json", media)
        _log("error", "CONFLICT")
        return _err("CONFLICT", "Unable to create local media directory for downloads.", media_id=item.get("id"))

    local_path = os.path.join(local_dir, f"{msg.get('id')}{safe_ext}")
    # Touch placeholder file to reflect "available locally"
    try:
        if not os.path.exists(local_path):
            with open(local_path, "wb") as f:
                f.write(b"")
    except Exception:
        item["download_status"] = "failed"
        item["last_error"] = "Unable to write local media file."
        item["updated_at"] = now
        _save("wa_media_items.json", media)
        _log("error", "CONFLICT")
        return _err("CONFLICT", "Unable to write downloaded media to disk.", media_id=item.get("id"))

    item["local_path"] = local_path
    item["download_status"] = "available"
    item["updated_at"] = now

    _save("wa_media_items.json", media)
    _log("ok", None)
    return {"media": item, "status": item.get("download_status"), "local_path": item.get("local_path"), "message": msg}

