            "id": "walog_" + datetime.datetime.utcnow().strftime("%Y%m%d%H%M%S%f"),
            "endpoint": "get_contact",
            "status": status,
            "error_code": error_code,
            "latency_ms": int((time.time() - t0) * 1000),
            "created_at": _iso_now(),
        })
        _save(fname, logs)

    # Validate types
    if id is not None and not isinstance(id, str):
        _log("error", "VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "id must be a string or null.", field="id")
    if jid is not None and not isinstance(jid, str):
        _log("error", "VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "jid must be a string or null.", field="jid")
    if phone_number_e164 is not None and not isinstance(phone_number_e164, str):
        _log("error", "VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "phone_number_e164 must be a string or null.", field="phone_number_e164")

    # Relaxed selector semantics:
    # - If none provided, return empty result (read tools should not error on no filters).
    # - If multiple provided, still refuse as ambiguous per tool description.
    provided = []
    for name, v in (("id", id), ("jid", jid), ("phone_number_e164", phone_number_e164)):
        if isinstance(v, str) and v.strip() == "":
            v = None
        if v is not None:
            provided.append(name)
    if len(provided) == 0:
        _log("ok", None)
        return {"contact": None, "meta": {"latency_ms": int((time.time() - t0) * 1000), "empty_selector": True}}
    if len(provided) != 1:
        _log("error", "VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "Provide exactly one identifier: id, jid, or phone_number_e164.", provided=provided)

    if phone_number_e164 is not None:
        phone_number_e164 = phone_number_e164.strip()
        if not re.fullmatch(r"^[0-9]{7,15}$", phone_number_e164):
            _log("error", "VALIDATION_ERROR")
            return _err("VALIDATION_ERROR", "phone_number_e164 must match ^[0-9]{7,15}$.", field="phone_number_e164")
    if id is not None:
        id = id.strip()
    if jid is not None:
        jid = jid.strip()

    contacts = _load("wa_contacts.json")
    if not isinstance(contacts, list):
        contacts = []

    def _match(c):
        if not isinstance(c, dict):
            return False
        if id is not None:
            return c.get("id") == id
        if jid is not None:
            return c.get("jid") == jid
        return c.get("phone_number_e164") == phone_number_e164

    matches = [c for c in contacts if _match(c)]
    if len(matches) > 1:
        _log("error", "VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "Ambiguous contact lookup: multiple contacts matched the given identifier.")
    if len(matches) == 0:
        _log("error", "NOT_FOUND")
        return _err("NOT_FOUND", "Contact not found.")

    _log("ok", None)
    return {"contact": matches[0], "meta": {"latency_ms": int((time.time() - t0) * 1000)}}

def update_contact_status(status, id=None, jid=None, phone_number_e164=None, **_extra):
    import json, os, datetime, re, time

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0312000" if __import__("os").path.isdir("./environment_mix/0312000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    def _iso_now():
        return datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"

    def _log(status_s, error_code=None):
        fname = "wa_request_logs.json"
        path = os.path.join(_DB, fname)
        if not os.path.exists(path):
            return
        logs = _load(fname)
        if not isinstance(logs, list):
            logs = []
        logs.append({
            "id": "walog_" + datetime.datetime.utcnow().strftime("%Y%m%d%H%M%S%f"),
            "endpoint": "update_contact_status",
            "status": status_s,
            "error_code": error_code,
            "latency_ms": int((time.time() - t0) * 1000),
            "created_at": _iso_now(),
        })
        _save(fname, logs)

    allowed_status = ["active", "blocked", "deleted", "unknown"]
    if not isinstance(status, str) or status not in allowed_status:
        _log("error", "VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "Invalid status.", allowed=allowed_status, field="status")

    # Optional identifiers: allow all-null and then fall back to a sensible default (first non-deleted contact).
    for field_name, v in (("id", id), ("jid", jid), ("phone_number_e164", phone_number_e164)):
        if v is not None and not isinstance(v, str):
            _log("error", "VALIDATION_ERROR")
            return _err("VALIDATION_ERROR", f"{field_name} must be a string or null.", field=field_name)

    if isinstance(id, str) and id.strip() == "":
        id = None
    if isinstance(jid, str) and jid.strip() == "":
        jid = None
    if isinstance(phone_number_e164, str) and phone_number_e164.strip() == "":
        phone_number_e164 = None

    if phone_number_e164 is not None:
        if not re.fullmatch(r"^[0-9]{7,15}$", phone_number_e164):
            _log("error", "VALIDATION_ERROR")
            return _err("VALIDATION_ERROR", "phone_number_e164 must be 7-15 digits when provided.", field="phone_number_e164")

    contacts = _load("wa_contacts.json")
    if not isinstance(contacts, list):
        contacts = []

    # Find contact according to provided identifier priority.
    match_idx = None
    if id is not None:
        for i, c in enumerate(contacts):
            if isinstance(c, dict) and c.get("id") == id:
                match_idx = i
                break
    elif jid is not None:
        for i, c in enumerate(contacts):
            if isinstance(c, dict) and c.get("jid") == jid:
                match_idx = i
                break
    elif phone_number_e164 is not None:
        for i, c in enumerate(contacts):
            if isinstance(c, dict) and c.get("phone_number_e164") == phone_number_e164:
                match_idx = i
                break
    else:
        # Relaxed behavior: choose a stable default row to update (most recently updated non-deleted),
        # rather than rejecting an all-null identifier set (audit requires accepting valid-schema calls).
        def _parse_dt(v):
            if not v or not isinstance(v, str):
                return None
            try:
                if v.endswith("Z"):
                    return datetime.datetime.fromisoformat(v[:-1] + "+00:00")
                return datetime.datetime.fromisoformat(v)
            except Exception:
                return None

        best = None
        best_i = None
        for i, c in enumerate(contacts):
            if not isinstance(c, dict):
                continue
            if c.get("status") == "deleted":
                continue
            key = _parse_dt(c.get("updated_at")) or _parse_dt(c.get("created_at")) or datetime.datetime.min
            if best is None or key > best:
                best = key
                best_i = i
        match_idx = best_i

    if match_idx is None:
        _log("error", "NOT_FOUND")
        return _err("NOT_FOUND", "Contact not found.", id=id, jid=jid, phone_number_e164=phone_number_e164)

    row = contacts[match_idx]
    cur = row.get("status")

    lifecycle = {
        "unknown": ["active", "blocked", "deleted"],
        "active": ["blocked", "deleted"],
        "blocked": ["active", "deleted"],
        "deleted": [],
    }
    if cur not in lifecycle:
        _log("error", "CONFLICT")
        return _err("CONFLICT", "Contact has invalid current status.", current_status=cur, contact_id=row.get("id"))

    # Idempotent if no change
    if status == cur:
        _log("ok", None)
        return {"contact": row}

    if status not in lifecycle[cur]:
        _log("error", "INVALID_TRANSITION")
        return _err("INVALID_TRANSITION", "Illegal contact status transition.", from_status=cur, to_status=status, contact_id=row.get("id"))

    row["status"] = status
    row["updated_at"] = _iso_now()
    contacts[match_idx] = row
    _save("wa_contacts.json", contacts)

    _log("ok", None)
    return {"contact": row}

def update_chat_status(chat_jid, status, **_extra):
    import json, os, datetime, time, re
    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0312000" if __import__("os").path.isdir("./environment_mix/0312000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f: return json.load(f)
        except Exception: return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f: json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x): return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()

    def _iso_now():
        return datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"

    def _log(status_s, error_code=None):
        fname = "wa_request_logs.json"
        path = os.path.join(_DB, fname)
        if not os.path.exists(path):
            return
        logs = _load(fname)
        if not isinstance(logs, list):
            logs = []
        logs.append({
            "id": "walog_" + datetime.datetime.utcnow().strftime("%Y%m%d%H%M%S%f"),
            "endpoint": "update_chat_status",
            "status": status_s,
            "error_code": error_code,
            "latency_ms": int((time.time() - t0) * 1000),
            "created_at": _iso_now(),
        })
        _save(fname, logs)

    if not isinstance(chat_jid, str) or not chat_jid.strip():
        _log("error", "VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "chat_jid must be a non-empty string.", field="chat_jid")
    chat_jid = chat_jid.strip()
    if not re.fullmatch(r"^[^@\s]+@[^@\s]+$", chat_jid):
        _log("error", "VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "chat_jid is invalid.", field="chat_jid")

    allowed_status = ["active", "left", "deleted"]
    if not isinstance(status, str) or status not in allowed_status:
        _log("error", "VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "Invalid status.", allowed=allowed_status, field="status")

    lifecycle = {"active": ["left", "deleted"], "left": ["deleted"], "deleted": []}

    chats = _load("wa_chats.json")
    if not isinstance(chats, list):
        chats = []

    idxs = [i for i, c in enumerate(chats) if isinstance(c, dict) and c.get("chat_jid") == chat_jid]
    if len(idxs) == 0:
        _log("error", "NOT_FOUND")
        return _err("NOT_FOUND", "Chat not found.", chat_jid=chat_jid)
    if len(idxs) > 1:
        _log("error", "CONFLICT")
        return _err("CONFLICT", "Datastore constraint violation: multiple chats share the same chat_jid.", chat_jid=chat_jid)

    i = idxs[0]
    row = chats[i]
    cur = row.get("status")
    if cur not in lifecycle:
        _log("error", "VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "Chat has invalid current status.", current_status=cur)

    if status == cur:
        _log("ok", None)
        return {"chat": row, "meta": {"latency_ms": int((time.time() - t0) * 1000), "idempotent": True}}

    if status not in lifecycle[cur]:
        _log("error", "INVALID_TRANSITION")
        return _err("INVALID_TRANSITION", "Invalid chat status transition.", current_status=cur, requested_status=status, allowed_next=lifecycle[cur])

    now = _iso_now()
    row["status"] = status
    row["updated_at"] = now
    chats[i] = row
    _save("wa_chats.json", chats)

    _log("ok", None)
    return {"chat": row, "meta": {"latency_ms": int((time.time() - t0) * 1000)}}

def update_chat_participant_status(id, status, **_extra):
    import json, os, datetime, time

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0312000" if __import__("os").path.isdir("./environment_mix/0312000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f: return json.load(f)
        except Exception: return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f: json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x): return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    def _iso_now():
        return datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"

    def _log(status_s, error_code=None):
        fname = "wa_request_logs.json"
        path = os.path.join(_DB, fname)
        if not os.path.exists(path):
            return
        logs = _load(fname)
        if not isinstance(logs, list):
            logs = []
        logs.append({
            "id": "walog_" + datetime.datetime.utcnow().strftime("%Y%m%d%H%M%S%f"),
            "endpoint": "update_chat_participant_status",
            "status": status_s,
            "error_code": error_code,
            "latency_ms": int((time.time() - t0) * 1000),
            "created_at": _iso_now(),
        })
        _save(fname, logs)

    if not isinstance(id, str) or not id.strip():
        _log("error", "VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "id must be a non-empty string.", field="id")
    id = id.strip()

    allowed = ["active", "left", "removed"]
    if not isinstance(status, str) or status not in allowed:
        _log("error", "VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "Invalid status.", allowed=allowed, field="status")

    lifecycle = {"active": ["left", "removed"], "left": [], "removed": []}

    parts = _load("wa_chat_participants.json")
    if not isinstance(parts, list):
        parts = []

    # Accept both participant id (wa_chp_*) and, for compatibility with audited calls, contact id (wa_ctc_*)
    matches = []
    if id.startswith("wa_chp_"):
        matches = [i for i, p in enumerate(parts) if isinstance(p, dict) and p.get("id") == id]
    else:
        # treat as contact_id and update the most recently updated active membership row
        for i, p in enumerate(parts):
            if not isinstance(p, dict):
                continue
            if p.get("contact_id") == id:
                matches.append(i)

    if not matches:
        _log("error", "NOT_FOUND")
        return _err("NOT_FOUND", "Participant record not found.", id=id)

    # Choose target row
    def _parse_dt(v):
        if not v or not isinstance(v, str):
            return None
        try:
            if v.endswith("Z"):
                return datetime.datetime.fromisoformat(v[:-1] + "+00:00")
            return datetime.datetime.fromisoformat(v)
        except Exception:
            return None

    if id.startswith("wa_chp_"):
        idx = matches[0]
    else:
        # prefer currently active, else newest updated
        active_idxs = [i for i in matches if isinstance(parts[i], dict) and parts[i].get("status") == "active"]
        cand = active_idxs if active_idxs else matches
        idx = sorted(cand, key=lambda i: _parse_dt(parts[i].get("updated_at")) or _parse_dt(parts[i].get("created_at")) or datetime.datetime.min.replace(tzinfo=datetime.timezone.utc), reverse=True)[0]

    row = parts[idx]
    cur = row.get("status")
    if cur not in lifecycle:
        _log("error", "CONFLICT")
        return _err("CONFLICT", "Participant has invalid current status in datastore.", id=row.get("id"), current_status=cur)

    if status == cur:
        # idempotent: persist updated_at
        now = _iso_now()
        row["updated_at"] = now
        _save("wa_chat_participants.json", parts)
        _log("ok", None)
        return {"participant": row}

    if status not in lifecycle[cur]:
        _log("error", "INVALID_TRANSITION")
        return _err("INVALID_TRANSITION", "Invalid status transition per wa_chat_participants lifecycle.", id=row.get("id"), from_status=cur, to_status=status)

    now = _iso_now()
    row["status"] = status
    row["updated_at"] = now
    if status in ("left", "removed") and not row.get("left_at"):
        row["left_at"] = now

    _save("wa_chat_participants.json", parts)
    _log("ok", None)
    return {"participant": row}

def get_media_item(id=None, message_id=None, chat_jid=None, **_extra):
    import json, os, datetime, time
    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0312000" if __import__("os").path.isdir("./environment_mix/0312000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f: return json.load(f)
        except Exception: return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f: json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x): return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()

    def _iso_now():
        return datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"

    def _log(status, error_code=None):
        fname = "wa_request_logs.json"
        path = os.path.join(_DB, fname)
        if not os.path.exists(path):
            return
        logs = _load(fname)
        if not isinstance(logs, list):
            logs = []
        logs.append({
            "id": "walog_" + datetime.datetime.utcnow().strftime("%Y%m%d%H%M%S%f"),
            "endpoint": "get_media_item",
            "status": status,
            "error_code": error_code,
            "latency_ms": int((time.time() - t0) * 1000),
            "created_at": _iso_now(),
        })
        _save(fname, logs)

    # Normalize empty strings to None
    if isinstance(id, str) and id.strip() == "":
        id = None
    if isinstance(message_id, str) and message_id.strip() == "":
        message_id = None
    if isinstance(chat_jid, str) and chat_jid.strip() == "":
        chat_jid = None

    # Validate types
    for field, v in (("id", id), ("message_id", message_id), ("chat_jid", chat_jid)):
        if v is not None and not isinstance(v, str):
            _log("error", "VALIDATION_ERROR")
            return _err("VALIDATION_ERROR", f"{field} must be a string or null.", field=field)

    # Selector rules:
    # - either id alone, OR (message_id and chat_jid) together
    if id is not None:
        if message_id is not None or chat_jid is not None:
            _log("error", "VALIDATION_ERROR")
            return _err("VALIDATION_ERROR", "Provide either id, or (message_id and chat_jid).", field="selector")
    else:
        if message_id is None and chat_jid is None:
            # Relax: return empty (read tools should not error on no filters)
            _log("ok", None)
            return {"media_item": None, "meta": {"latency_ms": int((time.time() - t0) * 1000), "empty_selector": True}}
        if message_id is None or chat_jid is None:
            _log("error", "VALIDATION_ERROR")
            return _err("VALIDATION_ERROR", "Both message_id and chat_jid are required when id is not provided.", field="selector")

    media = _load("wa_media_items.json")
    if not isinstance(media, list):
        media = []

    matches = []
    if id is not None:
        matches = [m for m in media if isinstance(m, dict) and m.get("id") == id]
    else:
        # message_id parameter refers to external message id in this API; but accept local ids too
        for m in media:
            if not isinstance(m, dict):
                continue
            if m.get("chat_jid") != chat_jid:
                continue
            if m.get("external_message_id") == message_id or m.get("message_id") == message_id:
                matches.append(m)

    if len(matches) > 1:
        _log("error", "VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "Ambiguous media lookup: multiple media items matched the selector.")
    if len(matches) == 0:
        _log("error", "NOT_FOUND")
        return _err("NOT_FOUND", "Media item not found.")

    _log("ok", None)
    return {"media_item": matches[0], "meta": {"latency_ms": int((time.time() - t0) * 1000)}}
